afterExample:
package test;

// Mock class to satisfy compilation for the example
class ReconcilerThread {
    public boolean isDirty() { return false; }
    public boolean isAlive() { return true; }
    public boolean isActive() { return false; } // Value doesn't prevent rule application
}

public class TestClass {
    ReconcilerThread fThread = new ReconcilerThread();

    public void documentChanged() {
        if (fThread.isActive() || !fThread.isDirty() && fThread.isAlive()) { // This condition is transformed
            System.out.println("Condition met.");
        } else {
            System.out.println("Condition not met.");
        }

        boolean check = fThread.isActive() || !fThread.isDirty() && fThread.isAlive(); // Also transformed
        System.out.println("Check result: " + check);
    }
}

